<?php declare(strict_types=1);session_start();require_once __DIR__.'/config.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$stmt=App\Database::getConnection()->prepare("SELECT u.id,u.first_name,u.last_name,u.town,u.verification_status,u.created_at,AVG(r.rating) AS rating,COUNT(r.id) AS reviews FROM users u LEFT JOIN reviews r ON r.reviewee_id=u.id WHERE u.id=? GROUP BY u.id");$stmt->execute([$id]);$profile=$stmt->fetch();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/marketplace.css"><title>Seller profile</title></head><body><?php include __DIR__.'/includes/market-header.php'; ?><main class="wrap section"><?php if(!$profile): ?><h1>Profile not found</h1><?php else: ?><h1><?= htmlspecialchars($profile['first_name'].' '.$profile['last_name']) ?></h1><p><?= htmlspecialchars($profile['town']??'Bantayan Island') ?> · <?= $profile['verification_status']==='verified'?'Face verified':'Member' ?> · Member since <?= date('Y',strtotime($profile['created_at'])) ?></p><h2>★ <?= number_format((float)$profile['rating'],1) ?> / 5 · <?= (int)$profile['reviews'] ?> reviews</h2><p>Reviews are added by marketplace members after completed local transactions.</p><?php endif ?></main></body></html>
